import hashlib
import math
from bitarray import bitarray

class BloomFilter:
    def __init__(self, items_count, fp_prob):
        # Calculate Optimal Array Size (m)
        self.size = self.get_size(items_count, fp_prob)
        # Calculate Optimal Number of Hash Functions (k)
        self.hash_count = self.get_hash_count(self.size, items_count)
        # Initialize bit array to all 0s
        self.bit_array = bitarray(self.size)
        self.bit_array.setall(0)

    def add(self, item):
        for i in range(self.hash_count):
            # Create k deterministic hashes using a salt (str(i))
            digest = hashlib.md5((item + str(i)).encode('utf8')).hexdigest()
            index = int(digest, 16) % self.size
            self.bit_array[index] = 1

    def check(self, item):
        for i in range(self.hash_count):
            digest = hashlib.md5((item + str(i)).encode('utf8')).hexdigest()
            index = int(digest, 16) % self.size
            # If any bit is 0, the item is DEFINITELY NOT in the set
            if self.bit_array[index] == 0:
                return False
        # If all bits are 1, it is PROBABLY in the set
        return True

    @staticmethod
    def get_size(n, p):
        m = -(n * math.log(p)) / (math.log(2)**2)
        return int(m)

    @staticmethod
    def get_hash_count(m, n):
        k = (m/n) * math.log(2)
        return int(k)

# Usage:
# bloom = BloomFilter(items_count=1000000, fp_prob=0.01)
# bloom.add("malicious-domain.com")
# bloom.check("google.com") -> False (Guaranteed)
# bloom.check("malicious-domain.com") -> True (Probably)

